    category,
    region,
    country,
    shortDescription,
    longDescription,
    dateInscribed,
    danger,
    latitude,
    longitude,
    image
) VALUES (
    '6a68c88a63995188853bd5ad',
    2024,
    'Aqueduct of Padre Tembleque Hydraulic System',
    'Cultural',
    'Americas',
    'Mexico',
    'This 16 th century aqueduct is located between the states of Mexico and Hidalgo, on the Central Mexican Plateau. This heritage canal system encompasses a water catchment area, springs, canals, distribution tanks and arcaded aqueduct bridges. The site incorporates the highest single-level arcade ever built in an aqueduct. Initiated by the Franciscan friar, Padre Tembleque, and built with support from the local indigenous communities, this hydraulic system is an example of the exchange of influences between the European tradition of Roman hydraulics and traditional Mesoamerican construction techniques, including the use of adobe.',
    NULL,
    2015,
    0,
    19.83527778,
    -98.66256667,
    'https://res.cloudinary.com/mvzqmmua/image/upload/v1785278361/Nomia/Sites/site-2024.jpg'
);
